mapper.select:
SELECT id, cell_id, target_cell_id, route_epoch, state, cutoff_at, version
FROM warehouse_route
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

mapper.update:
UPDATE warehouse_route
SET state=#{state}, target_cell_id=#{targetCellId}, cutoff_at=#{cutoff}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND version=#{expected}
AND state=#{fromState}

UPDATE warehouse_route
SET route_epoch=#{epoch}, state=#{state}, cell_id=#{cellId}, target_cell_id=#{targetCellId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND version=#{expected}

UPDATE location_gate
SET state=#{state}, reason_code=#{reason}, fence_epoch=fence_epoch+1, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

    AND state='OPEN'
    AND state='MAINTENANCE' AND reason_code='WAREHOUSE_MIGRATION'
